async function persist(next){if(!key)throw Error('Kho đã khóa.');if(busy)throw Error('Đang lưu, vui lòng thử lại.');busy=true;const generation=epoch;try{const envelope=await seal(next,key,salt);if(generation!==epoch)throw Error('Kho đã khóa; thay đổi chưa được lưu.');await navigator.locks.request('safeincloud-write',()=>{if(localStorage.getItem(STORE)!==expected)throw Error('Kho đã đổi ở cửa sổ khác. Khóa và mở lại trước khi lưu.');const encoded=JSON.stringify(envelope);localStorage.setItem(STORE,encoded);expected=encoded});items=next;return envelope}finally{busy=false}}
