function isSecret(name){return !/^(login|url|notes|tài khoản|ghi chú|địa chỉ)$/i.test(name)}
function resetPasswords(){document.querySelectorAll('[data-password]').forEach(b=>{const input=$(b.dataset.password);input.type='password';b.textContent='Hiện';b.setAttribute('aria-pressed','false')})}
function addField(name='',value=''){const row=element('div',undefined,'field-editor'),n=element('input'),v=element(name==='Notes'?'textarea':'input');n.value=name;n.placeholder='Tên trường';n.required=true;n.maxLength=100;n.setAttribute('aria-label','Tên trường');v.value=value;v.setAttribute('aria-label','Giá trị trường');v.autocomplete='off';if(v.tagName==='INPUT')v.type=isSecret(name)?'password':'text';const toggle=btn('Hiện',()=>{const show=v.type==='password';v.type=show?'text':'password';toggle.textContent=show?'Ẩn':'Hiện';toggle.setAttribute('aria-pressed',String(show))});toggle.setAttribute('aria-label','Hiện hoặc ẩn giá trị');toggle.hidden=!isSecret(name)||v.tagName==='TEXTAREA';n.oninput=()=>{if(v.tagName==='INPUT'){v.type=isSecret(n.value)?'password':'text';toggle.hidden=!isSecret(n.value);toggle.textContent='Hiện';toggle.setAttribute('aria-pressed','false')}};row.append(n,v,toggle,btn('×',()=>row.remove()));$('fields').append(row)}
