$('unlock-form').onsubmit=e=>{e.preventDefault();run(async()=>{$('unlock').disabled=true;try{const saved=localStorage.getItem(STORE),pw=$('master').value;const generation=epoch;if(saved){const result=await open(JSON.parse(saved),pw);if(epoch!==generation)return;({key,salt,items}=result);expected=saved}else{if(Array.from(pw).length<6||pw!==$('repeat').value)throw Error('Mật khẩu cần ít nhất 6 ký tự và hai lần nhập phải giống nhau.');salt=crypto.getRandomValues(new Uint8Array(16));key=await derive(pw,salt);if(epoch!==generation)return;expected=null;await persist([])}if(pendingImport.length){const incoming=pendingImport;await persist([...items,...incoming]);pendingImport=[];toast(`Đã nhập ${incoming.length} mục.`)}$('master').value='';$('repeat').value='';resetPasswords();lastActivity=Date.now();$('gate').hidden=true;$('workspace').hidden=false;render()}finally{$('unlock').disabled=false}})};
$('edit-form').onsubmit=e=>{e.preventDefault();run(async()=>{const fields={};for(const row of $('fields').children){const n=row.children[0].value.trim();if(!n||Object.hasOwn(fields,n))throw Error('Tên trường không được trống hoặc trùng nhau.');Object.defineProperty(fields,n,{value:row.children[1].value,enumerable:true})}const record={id:editing||crypto.randomUUID(),title:$('title').value.trim(),category:$('category').value,fields,updatedAt:new Date().toISOString()};if(!record.title)throw Error('Hãy nhập tên mục.');await persist(editing?items.map(x=>x.id===editing?record:x):[...items,record]);selected=record.id;$('editor').close();$('fields').replaceChildren();render();window.dispatchEvent(new Event('vault-detail'));toast('Đã lưu mã hóa.')})};
$('add').onclick=()=>edit();$('add-field').onclick=()=>addField();$('generate').onclick=()=>{let row=[...$('fields').children].find(r=>r.children[0].value==='Password');if(!row){addField('Password','');row=$('fields').lastChild}row.children[1].value=generate()};$('search').oninput=render;$('lock').onclick=lock;
