function chooseFile(mode){$('file').value='';$('file').accept=mode==='csv'?'.csv,text/csv':'.vault,.json,application/json';$('file').onchange=()=>run(async()=>{const file=$('file').files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('File vượt quá 10 MB.');const text=await file.text();if(mode==='csv'){const imported=parseCSV(text);if(!imported.length){toast('File có đúng cấu trúc nhưng không có mục dữ liệu.');return}if(!key){pendingImport=imported;$('gate-description').textContent=`Đã chọn ${imported.length} mục. Mở khóa hoặc tạo kho để nhập và mã hóa dữ liệu.`;toast('Nhập mật khẩu chính để hoàn tất Import.');return}if(items.length+imported.length>20000)throw Error('Kho vượt quá 20.000 mục.');if(await confirmAction('Nhập CSV',`Nhập ${imported.length} mục vào kho? Các trường OTP và ghi chú sẽ được giữ nguyên. Mục trùng vẫn được nhập.`)){await persist([...items,...imported]);render();toast(`Đã nhập ${imported.length} mục.`)}}else await restoreEnvelope(JSON.parse(text));$('file').value=''});$('file').click()}
