async function googleToken(){if(token&&Date.now()<tokenExpiry)return token;if(!window.google?.accounts?.oauth2)await new Promise((res,rej)=>{const s=element('script');s.src='https://accounts.google.com/gsi/client';s.onload=res;s.onerror=()=>rej(Error('Không tải được đăng nhập Google. Kiểm tra kết nối.'));document.head.append(s)});oauthPending=true;return new Promise((resolve,reject)=>{const client=google.accounts.oauth2.initTokenClient({client_id:DEFAULT_CLIENT,scope:'https://www.googleapis.com/auth/drive.appdata',callback:r=>{oauthPending=false;if(r.error)return reject(Error('Google từ chối đăng nhập: '+r.error));token=r.access_token;tokenExpiry=Date.now()+(Number(r.expires_in)-60)*1000;resolve(token)},error_callback:()=>{oauthPending=false;reject(Error('Đăng nhập chưa hoàn tất. Kiểm tra popup và Authorized JavaScript origins.'))}});client.requestAccessToken({prompt:'select_account'})})}
async function driveFetch(path,options={}){const t=await googleToken();const r=await fetch('https://www.googleapis.com/'+path,{...options,headers:{Authorization:'Bearer '+t,...options.headers}});if(!r.ok){if(r.status===401){token=null;tokenExpiry=0}throw Error(`Google Drive báo lỗi ${r.status}. Kiểm tra quyền Drive API và đăng nhập lại.`)}return r}
async function upload(){if(!key)throw Error('Mở khóa kho trước khi lưu Drive.');const envelope=localStorage.getItem(STORE);const boundary='safeincloud_'+crypto.randomUUID(),name='SafeinCloud-'+new Date().toISOString()+'.vault';const body=`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify({name,parents:['appDataFolder'],appProperties:{app:'safeincloud-v1'}})}\r\n--${boundary}\r\nContent-Type: application/json\r\n\r\n${envelope}\r\n--${boundary}--`;await driveFetch('upload/drive/v3/files?uploadType=multipart',{method:'POST',headers:{'Content-Type':'multipart/related; boundary='+boundary},body});$('drive-status').textContent='Đã lưu bản mã lên Drive · '+new Date().toLocaleTimeString('vi');toast('Đã lưu bản sao mới trên Drive. Các bản cũ được giữ để tránh ghi đè dữ liệu.')}
async function pull(){const q="trashed = false and appProperties has { key='app' and value='safeincloud-v1' }";const r=await driveFetch('drive/v3/files?spaces=appDataFolder&pageSize=1&orderBy=createdTime%20desc&fields=files(id,name)&q='+encodeURIComponent(q));const data=await r.json();if(!data.files.length)throw Error('Tài khoản Google này chưa có kho SafeinCloud.');const f=await driveFetch('drive/v3/files/'+encodeURIComponent(data.files[0].id)+'?alt=media');await restoreEnvelope(await f.json())}
$('sync').onclick=()=>run(async()=>{if(await confirmAction('Lưu lên Google Drive','Tạo bản sao mã hóa mới trên tài khoản Google bạn chọn. Để lấy dữ liệu từ thiết bị khác, chọn “Mở kho từ Google Drive” ở màn hình khóa.'))await upload()});$('gate-drive').onclick=()=>run(pull);
document.querySelectorAll('[data-password]').forEach(b=>b.onclick=()=>{const input=$(b.dataset.password),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Ẩn':'Hiện';b.setAttribute('aria-pressed',String(show))});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());['pointerdown','keydown','input'].forEach(e=>document.addEventListener(e,()=>lastActivity=Date.now(),{passive:true}));setInterval(()=>{if(key&&Date.now()-lastActivity>300000)lock()},1000);document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();if(key&&!oauthPending)lock();else if(key){$('detail').replaceChildren();$('fields').replaceChildren();document.querySelectorAll('dialog[open]').forEach(x=>x.close())}}else if(hiddenAt&&Date.now()-hiddenAt>300000)lock();else if(key)render()});window.addEventListener('storage',e=>{if(e.key===STORE){lock();expected=e.newValue;toast('Kho đã thay đổi ở cửa sổ khác. Hãy mở khóa lại.')}});window.addEventListener('pagehide',lock);gate();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

